exception_handlers.body:
except Exception:
    logger.exception('Agent %s action %s failed', agent_id, action.kind.value)
    return HiveActionResult(action_id=action.id, success=False, output='Exception during action execution')

except Exception:
    logger.exception('Error reducing event %s', hevt.id)
    result['errors'].append(f'reduce_failed:{hevt.id}')

except Exception:
    logger.exception('Error polling health from agent %s', agent_id)
    result.setdefault('errors', []).append(f'health_poll_failed:{agent_id}')

except Exception as exc:
    logger.exception('Error executing action %s on %s', action.id, target)
    agent_results[target] = {'success': False, 'error': str(exc)}

except Exception:
    logger.exception('Error generating text report')
    return 'ERROR: Could not generate health report'

except Exception:
    logger.exception('Error polling events from agent %s', agent_id)
    return []

except OSError:
    try:
        os.unlink(path)
    except OSError:
        pass
    raise

except OSError:
    try:
        os.unlink(tmp)
    except OSError:
        pass
    raise

except OSError as exc:
    self._set_fence('unwritable', f'rebind journal cannot be created or read ({exc}); no journaled rebind is replayed', found_at_startup=True)
    return []

except OSError as exc:
    self._set_fence('changed', f'journal cannot be opened ({exc})')
    return False

except (_JournalChanged, OSError) as exc:
    self._set_fence('changed', f'verify_journal: {exc}')
    return False

except OSError as exc:
    try:
        os.ftruncate(fd, size)
        os.fsync(fd)
    except OSError as exc2:
        raise _JournalIndeterminate(f'{exc}; rollback failed: {exc2}') from exc2
    raise

except OSError as exc:
    logger.error('Refused hive rebind of %s: %s record write failed and was rolled back durably (%s)%s', what, step, exc, '; the pending record has no commit and is never replayed' if step == 'commit' else '')
    return False

except Exception:
    logger.exception('Error querying agent %s store', agent_id)
    return []
